import { uploadFile } from '@uploadcare/upload-client'

const UPLOADCARE_PUBLIC_KEY =
	process.env.EXPO_PUBLIC_UPLOADCARE_PUBLIC_KEY || ''

export interface UploadImageResult {
	uuid: string
	url: string
	cdnUrl: string
	originalFilename: string
	size: number
	mimeType: string
}

export async function uploadImageToUploadcare(
	uri: string,
	filename?: string
): Promise<UploadImageResult> {
	try {
		const mimeType = getMimeTypeFromUri(uri)
		const actualFilename = filename || getFilenameFromUri(uri)

		const file = {
			uri: uri,
			name: actualFilename,
			type: mimeType
		}

		const result = await uploadFile(file, {
			publicKey: UPLOADCARE_PUBLIC_KEY,
			store: 'auto',
			metadata: {
				source: 'mobile-app'
			}
		})

		const cdnUrl = `https://ucarecdn.com/${result.uuid}/`

		return {
			uuid: result.uuid,
			url: cdnUrl,
			cdnUrl: cdnUrl,
			originalFilename: result.name || actualFilename,
			size: result.size || 0,
			mimeType: result.mimeType || mimeType
		}
	} catch (error) {
		console.error('Error uploading image to Uploadcare:', error)
		throw error
	}
}

function getMimeTypeFromUri(uri: string): string {
	const extension = uri.split('.').pop()?.toLowerCase()
	const mimeTypes: Record<string, string> = {
		jpg: 'image/jpeg',
		jpeg: 'image/jpeg',
		png: 'image/png',
		gif: 'image/gif',
		webp: 'image/webp',
		heic: 'image/heic',
		heif: 'image/heif'
	}
	return mimeTypes[extension || ''] || 'image/jpeg'
}

function getFilenameFromUri(uri: string): string {
	const parts = uri.split('/')
	return parts[parts.length - 1] || `image-${Date.now()}.jpg`
}
